from pathlib import Path
import json,csv
r=Path(__file__).parent;data=json.loads((r/'results.json').read_text());rows=[];lines=['# Final advancing natural local-first benchmark','', 'Prompts contain no model-selection instruction. Fresh Telegram diagnostic sessions, production message handler, actual delivery. Qwen-first policy and measured-step early handoff; cloud work may continue beyond the 60-second design target. An overrun is flagged rather than counted as meeting the target. Per-test token/cost/time deltas were delivered immediately in Telegram. References are the most recent natural-route checks, not forced-cloud runs. Cache warmness, live source state and tool paths can differ. Output includes reasoning.','', '| Test | Time / delta | Cloud input / delta | Cloud output / delta | Cost / delta | Target |','|---|---:|---:|---:|---:|---|']
for x in data:
 u=x['usage'];d=x['deltas'];inp=u['fresh']+u['cached'];out=u['output']+u['reasoning'];row={'id':x['id'],'name':x['name'],'seconds':x['seconds'],'seconds_delta':d['seconds'],'cloud_input':inp,'cloud_input_delta':d['cloudInput'],'cloud_output':out,'cloud_output_delta':d['cloudOutput'],'cached_tokens':u['cached'],'cost':u['cost'],'cost_delta':d['cost'],'cloud_calls':u['requests'],'target_exceeded':x['targetExceeded'],'reply_ok':x['ok']};rows.append(row);lines.append(f"| {x['id']}. {x['name']} | {x['seconds']:.1f}s / {d['seconds']:+.1f}s | {inp:,} / {d['cloudInput']:+,} | {out:,} / {d['cloudOutput']:+,} | ${u['cost']:.8f} / {d['cost']:+.8f} | {'over 60s' if x['targetExceeded'] else 'under 60s'} |")
lines+=['',f"Completed replies: {sum(x['reply_ok'] for x in rows)}/{len(rows)}. Measured worst elapsed: {max(x['seconds'] for x in rows):.1f}s. This is not a proven upper bound for all requests or a certification of answer correctness.",'', 'Full prompts, references, responses and per-test usage are retained in results.json. General payload optimization remains disabled outside pilot test sessions. No device/registry writes, model installation or GPU configuration change is part of this benchmark.']
